local Tabs = {}
local function newTab(key, label, title, sub)
    local btn = new("TextButton", {Parent = Nav, Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = C.acc,
        BackgroundTransparency = 1, Text = "", AutoButtonColor = false})
    corner(btn, 8)
    local bar = new("Frame", {Parent = btn, Position = UDim2.fromOffset(0, 7), Size = UDim2.fromOffset(3, 16),
        BackgroundColor3 = C.acc2, BorderSizePixel = 0, Visible = false})
    corner(bar, 2)
    local lb = new("TextLabel", {Parent = btn, BackgroundTransparency = 1, Position = UDim2.fromOffset(16, 0),
        Size = UDim2.new(1, -20, 1, 0), Text = label, Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = C.sub, TextXAlignment = Enum.TextXAlignment.Left})
    local page = new("ScrollingFrame", {Parent = Content, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
        CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3,
        ScrollBarImageColor3 = C.acc, BorderSizePixel = 0, Visible = false})
    list(page, 8)
    new("UIPadding", {Parent = page, PaddingRight = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10)})
    local function select()
        for _, t in pairs(Tabs) do
            t.page.Visible = false t.bar.Visible = false
            tween(t.btn, 0.15, {BackgroundTransparency = 1})
            tween(t.lb, 0.15, {TextColor3 = C.sub})
        end
        page.Visible = true bar.Visible = true
        tween(btn, 0.15, {BackgroundTransparency = 0.82})
        tween(lb, 0.15, {TextColor3 = Color3.new(1, 1, 1)})
        TitleLbl.Text = title SubLbl.Text = sub
    end
    btn.MouseButton1Click:Connect(select)
    Tabs[key] = {btn = btn, page = page, bar = bar, lb = lb, select = select}
    return page
end

