        Size = UDim2.new(1, -28, 0, 1), BackgroundColor3 = C.line, BackgroundTransparency = 0.93, BorderSizePixel = 0})
    return r
end

local function rowText(r, text, w)
    return new("TextLabel", {Parent = r, BackgroundTransparency = 1, Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(w or 1, -28, 1, 0), Text = text, Font = Enum.Font.GothamMedium, TextSize = 12.5,
        TextColor3 = C.text, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd})
end

local function makeSwitch(parent, flag)
    local sw = new("Frame", {Parent = parent, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0),
        Size = UDim2.fromOffset(40, 22), BackgroundColor3 = C.off})
    corner(sw, 11)
    local g = new("UIGradient", {Parent = sw, Color = ColorSequence.new(C.acc, C.acc2), Enabled = false})
    local knob = new("Frame", {Parent = sw, Size = UDim2.fromOffset(16, 16), Position = UDim2.fromOffset(3, 3),
        BackgroundColor3 = Color3.new(1, 1, 1)})
    corner(knob, 8)
    local function paint(v)
        g.Enabled = v
        sw.BackgroundColor3 = v and Color3.new(1, 1, 1) or C.off
        tween(knob, 0.15, {Position = v and UDim2.fromOffset(21, 3) or UDim2.fromOffset(3, 3)})
    end
    paint(Flags[flag] and true or false)
    AddView(flag, paint)
end

local function Toggle(g, text, flag, hook)
    ensureFlag(flag)
    if hook then Hooks[flag] = hook end
    local r = Row(g, 38)
    local hit = new("TextButton", {Parent = r, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = ""})
    rowText(r, text, 0.8)
    makeSwitch(r, flag)
    hit.MouseButton1Click:Connect(function() SetFlag(flag, not Flags[flag]) end)
end

local function Slider(g, text, flag, min, max, default, step, cb)
    step = step or 1
    local v = Saved[flag]
    if type(v) ~= "number" then v = default end
    Flags[flag] = v
    Persist[flag] = true
    local r = Row(g, 52)
    new("TextLabel", {Parent = r, BackgroundTransparency = 1, Position = UDim2.fromOffset(14, 2),
        Size = UDim2.new(1, -100, 0, 26), Text = text, Font = Enum.Font.GothamMedium, TextSize = 12.5, TextColor3 = C.text,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd})
    local val = new("TextLabel", {Parent = r, BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -14, 0, 2), Size = UDim2.fromOffset(70, 26), Text = tostring(v),
        Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = C.acc2, TextXAlignment = Enum.TextXAlignment.Right})
    local track = new("Frame", {Parent = r, Position = UDim2.new(0, 14, 0, 34), Size = UDim2.new(1, -28, 0, 5),
        BackgroundColor3 = C.off})
    corner(track, 3)
    local fill = new("Frame", {Parent = track, Size = UDim2.fromScale((v - min) / (max - min), 1), BackgroundColor3 = Color3.new(1, 1, 1)})
    corner(fill, 3) gradient(fill, C.acc, C.acc2)
    local knob = new("Frame", {Parent = fill, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(1, 0.5),
        Size = UDim2.fromOffset(13, 13), BackgroundColor3 = Color3.new(1, 1, 1)})
    corner(knob, 7) stroke(knob, C.acc, 2)
    local dragging = false
    local function update(x)
        local a = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
        local n = min + (max - min) * a
        n = math.floor(n / step + 0.5) * step
        n = tonumber(string.format("%.3f", math.clamp(n, min, max)))
        Flags[flag] = n
        val.Text = tostring(n)
        fill.Size = UDim2.fromScale((n - min) / (max - min), 1)
        if cb then cb(n) end
        queueSave()
    end
    r.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            g.page.ScrollingEnabled = false
            update(i.Position.X)
        end
    end)
    Connect(UIS.InputChanged, function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
            update(i.Position.X)
        end
    end)
    Connect(UIS.InputEnded, function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            g.page.ScrollingEnabled = true
        end
    end)
end

