local function Input(g, text, flag, default, placeholder)
    local v = Saved[flag]
    if type(v) ~= "string" then v = default end
    Flags[flag] = v
    Persist[flag] = true
    local r = Row(g, 46)
    rowText(r, text, 0.4)
    local box = new("TextBox", {Parent = r, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0),
        Size = UDim2.new(0.6, -14, 0, 28), BackgroundColor3 = Color3.fromRGB(6, 4, 12), Text = v,
        PlaceholderText = placeholder or "", Font = Enum.Font.Gotham, TextSize = 12, TextColor3 = C.text,
        PlaceholderColor3 = C.sub, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left})
    corner(box, 8) stroke(box, C.acc, 1, 0.55)
    new("UIPadding", {Parent = box, PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10)})
    box.FocusLost:Connect(function() Flags[flag] = box.Text queueSave() end)
end

local function Dropdown(g, text, flag, getOpts, default, cb)
    local v = Saved[flag]
    if v == nil then v = default end
    Flags[flag] = v
    Persist[flag] = true
    local box = new("Frame", {Parent = g.frame, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 38),
        AutomaticSize = Enum.AutomaticSize.Y, ClipsDescendants = true})
    local head = new("TextButton", {Parent = box, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 38), Text = ""})
    rowText(head, text, 0.5)
    local cur = new("TextLabel", {Parent = head, BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -14, 0, 0), Size = UDim2.new(0.5, -14, 1, 0), Text = tostring(v or "-") .. "  ▾",
        Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = C.acc2, TextXAlignment = Enum.TextXAlignment.Right,
        TextTruncate = Enum.TextTruncate.AtEnd})
    local items = new("Frame", {Parent = box, BackgroundTransparency = 1, Position = UDim2.fromOffset(0, 38),
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Visible = false})
    list(items, 0)
    local function choose(o)
        Flags[flag] = o
        cur.Text = tostring(o) .. "  ▾"
        items.Visible = false
        if cb then cb(o) end
        queueSave()
    end
    local function rebuild()
        for _, c in ipairs(items:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
        for _, o in ipairs(getOpts()) do
            local ob = new("TextButton", {Parent = items, Size = UDim2.new(1, -28, 0, 30), BackgroundColor3 = C.acc,
                BackgroundTransparency = 0.85, Text = "  " .. tostring(o), Font = Enum.Font.Gotham, TextSize = 12,
                TextColor3 = C.text, TextXAlignment = Enum.TextXAlignment.Left, AutoButtonColor = false, BorderSizePixel = 0})
            corner(ob, 6)
            ob.MouseButton1Click:Connect(function() choose(o) end)
        end
        new("Frame", {Parent = items, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 6)})
    end
    head.MouseButton1Click:Connect(function()
        if not items.Visible then rebuild() end
        items.Visible = not items.Visible
    end)
    new("Frame", {Parent = box, AnchorPoint = Vector2.new(0, 0), Position = UDim2.fromOffset(14, 37),
        Size = UDim2.new(1, -28, 0, 1), BackgroundColor3 = C.line, BackgroundTransparency = 0.93, BorderSizePixel = 0})
end

local function PlayerNames()
    local t = {}
    for _, p in ipairs(Players:GetPlayers()) do if p ~= LP then t[#t + 1] = p.Name end end
    if #t == 0 then t[1] = "(kosong)" end
    return t
end

